-- D1 (SQLite) initial schema: authentication + trainer core tables.
--
-- Conventions (all migrations):
--   * ids: TEXT UUID v4 generated by the server (crypto.randomUUID()).
--   * timestamps: TEXT ISO-8601 UTC with milliseconds, e.g. 2026-11-20T09:00:00.000Z.
--     The fixed width makes lexical order == chronological order, which the
--     lesson-overlap trigger and range queries rely on.
--   * dates: TEXT YYYY-MM-DD.
--   * booleans: INTEGER 0/1 with CHECK.
--   * JSON: TEXT with CHECK(json_valid(...)).
-- D1 always enforces foreign keys. Ownership that Postgres expressed with RLS is
-- expressed here with composite foreign keys (member_id, trainer_id) plus the
-- server authorization layer in lib/server/db/.
--
-- Source mapping: supabase/migrations/20260415000000_exercise_homework_init.sql,
-- 20260416000000_voice_coach_cadence.sql, 20260920000000_trainer_ownership_and_atomic_homework.sql,
-- 20260920115204_member_onboarding_imports.sql (member CHECKs),
-- 20260921171403_homework_assignment_v2.sql (homework/items columns).
-- See docs/CLOUDFLARE_MIGRATION.md for the full mapping table.

-- ── Better Auth core tables ────────────────────────────────────────────────
CREATE TABLE "user" (
  id TEXT PRIMARY KEY NOT NULL,
  name TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE,
  email_verified INTEGER NOT NULL DEFAULT 0 CHECK (email_verified IN (0, 1)),
  image TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE account (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
  account_id TEXT NOT NULL,
  provider_id TEXT NOT NULL,
  password TEXT,
  access_token TEXT,
  refresh_token TEXT,
  id_token TEXT,
  access_token_expires_at TEXT,
  refresh_token_expires_at TEXT,
  scope TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  UNIQUE (provider_id, account_id)
);
CREATE INDEX account_user_idx ON account(user_id);

CREATE TABLE session (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
  token TEXT NOT NULL UNIQUE,
  expires_at TEXT NOT NULL,
  ip_address TEXT,
  user_agent TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX session_user_idx ON session(user_id);
CREATE INDEX session_expiry_idx ON session(expires_at);

CREATE TABLE verification (
  id TEXT PRIMARY KEY NOT NULL,
  identifier TEXT NOT NULL,
  value TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX verification_identifier_idx ON verification(identifier);

-- Better Auth rate-limit storage ("database" mode). last_request is the epoch-ms
-- number Better Auth itself writes; it is a counter field, not a display timestamp.
CREATE TABLE rate_limit (
  id TEXT PRIMARY KEY NOT NULL,
  key TEXT NOT NULL UNIQUE,
  count INTEGER NOT NULL,
  last_request INTEGER NOT NULL
);

-- Invitation allowlist: sign-up is only possible for an email an operator added
-- (sha256 of the lower-cased email). Replaces Supabase open sign-up.
CREATE TABLE signup_allowlist (
  email_hash TEXT PRIMARY KEY NOT NULL CHECK (length(email_hash) = 64),
  expires_at TEXT NOT NULL,
  used_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- ── Trainer profile (was public.profiles + handle_new_trainer trigger) ─────
-- is_pro is only writable by operators (wrangler d1 execute); no app code path
-- updates it (audit NV-2).
CREATE TABLE profiles (
  id TEXT PRIMARY KEY NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
  email TEXT,
  name TEXT,
  is_pro INTEGER NOT NULL DEFAULT 0 CHECK (is_pro IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- ── Members ────────────────────────────────────────────────────────────────
CREATE TABLE members (
  id TEXT PRIMARY KEY NOT NULL,
  trainer_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
  name TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 100),
  phone TEXT NOT NULL CHECK (length(trim(phone)) BETWEEN 1 AND 30),
  package_total INTEGER NOT NULL DEFAULT 10 CHECK (package_total BETWEEN 1 AND 1000),
  package_remaining INTEGER NOT NULL DEFAULT 10,
  package_expires_on TEXT CHECK (package_expires_on IS NULL OR package_expires_on GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  end_state TEXT NOT NULL DEFAULT '' CHECK (length(end_state) <= 500),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CHECK (package_remaining BETWEEN 0 AND package_total),
  UNIQUE (id, trainer_id)
);
CREATE INDEX members_trainer_created_idx ON members(trainer_id, created_at DESC);

-- Audit C-1: the Free plan (5 members) is enforced by the database, not only the UI.
-- A single INSERT is atomic in SQLite, so concurrent registrations cannot exceed it.
CREATE TRIGGER members_free_plan_limit
BEFORE INSERT ON members
WHEN COALESCE((SELECT is_pro FROM profiles WHERE id = NEW.trainer_id), 0) = 0
 AND (SELECT count(*) FROM members WHERE trainer_id = NEW.trainer_id) >= 5
BEGIN
  SELECT RAISE(ABORT, 'free_plan_member_limit');
END;

-- A member can never be moved to another trainer.
CREATE TRIGGER members_trainer_immutable
BEFORE UPDATE OF trainer_id ON members
WHEN NEW.trainer_id IS NOT OLD.trainer_id
BEGIN
  SELECT RAISE(ABORT, 'trainer_id_immutable');
END;

-- ── Homework (was public.homework) ─────────────────────────────────────────
-- Audit NV-3: the member link token is never stored in plaintext.
--   token_hash   = sha256 hex of the token (lookup key for /h/[token])
--   token_sealed = AES-GCM ciphertext so the owning trainer can re-copy the link
CREATE TABLE homework (
  id TEXT PRIMARY KEY NOT NULL,
  trainer_id TEXT NOT NULL,
  member_id TEXT NOT NULL,
  token_hash TEXT NOT NULL UNIQUE CHECK (length(token_hash) = 64),
  token_sealed TEXT,
  token_expires_at TEXT NOT NULL,
  revoked_at TEXT,
  why TEXT NOT NULL CHECK (length(trim(why)) BETWEEN 1 AND 2000),
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'sent', 'opened', 'logged', 'revoked')),
  opening_line TEXT,
  assignment_purpose TEXT CHECK (assignment_purpose IS NULL OR assignment_purpose IN ('routine', 'focus', 'review')),
  burden_budget_seconds INTEGER CHECK (burden_budget_seconds IS NULL OR burden_budget_seconds > 0),
  source_homework_id TEXT REFERENCES homework(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  FOREIGN KEY (member_id, trainer_id) REFERENCES members(id, trainer_id) ON DELETE CASCADE,
  UNIQUE (id, trainer_id)
);
CREATE INDEX homework_trainer_created_idx ON homework(trainer_id, created_at DESC);
CREATE INDEX homework_member_created_idx ON homework(member_id, created_at DESC);
CREATE INDEX homework_source_idx ON homework(source_homework_id) WHERE source_homework_id IS NOT NULL;

CREATE TRIGGER homework_owner_immutable
BEFORE UPDATE OF trainer_id, member_id ON homework
WHEN NEW.trainer_id IS NOT OLD.trainer_id OR NEW.member_id IS NOT OLD.member_id
BEGIN
  SELECT RAISE(ABORT, 'homework_owner_immutable');
END;

-- A source homework must belong to the same trainer and member.
CREATE TRIGGER homework_source_same_owner
BEFORE INSERT ON homework
WHEN NEW.source_homework_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM homework s
  WHERE s.id = NEW.source_homework_id AND s.trainer_id = NEW.trainer_id AND s.member_id = NEW.member_id
)
BEGIN
  SELECT RAISE(ABORT, 'source_homework_not_found');
END;

CREATE TABLE homework_items (
  id TEXT PRIMARY KEY NOT NULL,
  homework_id TEXT NOT NULL REFERENCES homework(id) ON DELETE CASCADE,
  order_index INTEGER NOT NULL CHECK (order_index BETWEEN 1 AND 3),
  name TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 120),
  cue TEXT NOT NULL DEFAULT '' CHECK (length(cue) <= 1000),
  target_sets INTEGER NOT NULL DEFAULT 3 CHECK (target_sets BETWEEN 1 AND 99),
  target_reps TEXT NOT NULL DEFAULT '10회' CHECK (length(trim(target_reps)) BETWEEN 1 AND 50),
  effort_kind TEXT NOT NULL DEFAULT 'reps' CHECK (effort_kind IN ('reps', 'hold')),
  reps INTEGER,
  hold_seconds INTEGER,
  seconds_per_rep REAL NOT NULL DEFAULT 3.0 CHECK (seconds_per_rep BETWEEN 0.5 AND 10),
  rest_seconds INTEGER NOT NULL DEFAULT 20 CHECK (rest_seconds BETWEEN 0 AND 180),
  per_side INTEGER NOT NULL DEFAULT 0 CHECK (per_side IN (0, 1)),
  exercise_snapshot TEXT CHECK (exercise_snapshot IS NULL OR (json_valid(exercise_snapshot) AND json_type(exercise_snapshot) = 'object')),
  requirement TEXT NOT NULL DEFAULT 'required' CHECK (requirement IN ('required', 'optional')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CHECK (
    (effort_kind = 'reps' AND reps IS NOT NULL AND reps BETWEEN 1 AND 50)
    OR (effort_kind = 'hold' AND hold_seconds IS NOT NULL AND hold_seconds BETWEEN 1 AND 300)
  ),
  UNIQUE (homework_id, order_index),
  UNIQUE (id, homework_id)
);

CREATE TABLE homework_logs (
  id TEXT PRIMARY KEY NOT NULL,
  homework_id TEXT NOT NULL REFERENCES homework(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('complete', 'partial', 'cant', 'pain', 'note')),
  payload TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(payload) AND json_type(payload) = 'object'),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX homework_logs_homework_idx ON homework_logs(homework_id, created_at);

-- ── Session notes ──────────────────────────────────────────────────────────
CREATE TABLE session_notes (
  id TEXT PRIMARY KEY NOT NULL,
  trainer_id TEXT NOT NULL,
  member_id TEXT NOT NULL,
  note TEXT NOT NULL CHECK (length(trim(note)) BETWEEN 1 AND 10000),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  FOREIGN KEY (member_id, trainer_id) REFERENCES members(id, trainer_id) ON DELETE CASCADE
);
CREATE INDEX session_notes_member_idx ON session_notes(member_id, created_at DESC);
